INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('아사쿠사 도리노이치 (니노토리)', '浅草酉の市（二の酉）', '東京都', '台東区', DATE '2026-11-19', DATE '2026-11-19', 2026, 35.723000, 139.792500, '11월 ''닭의 날''에 오토리 신사에서 열리는 장사 번창 기원 시장. 행운을 긁어모은다는 장식 갈퀴(구마데)를 사면 상인들이 박수로 축하해 준다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('지치부 요마쓰리', '秩父夜祭', '埼玉県', '秩父市', DATE '2026-12-02', DATE '2026-12-03', 2026, 35.997500, 139.084000, '지치부 신사의 예대제로 일본 3대 수레 축제 중 하나. 3일 밤 등불을 두른 수레 6기가 단고자카 언덕을 오르고, 겨울 불꽃놀이가 하늘을 채운다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('다카야마 마쓰리 (봄)', '春の高山祭（山王祭）', '岐阜県', '高山市', DATE '2027-04-14', DATE '2027-04-15', 2027, 36.135000, 137.262000, '히에 신사의 제례로 일본 3대 아름다운 축제 중 하나. 화려한 수레 12기가 옛 거리에 서고, 꼭두각시 인형 공연(가라쿠리)과 밤 수레 행렬이 이어진다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('산자 마쓰리', '三社祭', '東京都', '台東区', DATE '2027-05-14', DATE '2027-05-16', 2027, 35.715000, 139.797500, '아사쿠사 신사의 예대제로 에도 3대 마쓰리 중 하나. 사흘간 약 100기의 동네 가마가 아사쿠사 거리를 누비고, 마지막 날 본사 가마 3기가 나온다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('가나자와 햐쿠만고쿠 마쓰리', '金沢百万石まつり', '石川県', '金沢市', DATE '2027-06-04', DATE '2027-06-06', 2027, 36.578000, 136.648000, '번주 마에다 도시이에의 가나자와성 입성을 기념하는 축제. 토요일에 무사 행렬(햐쿠만고쿠 행렬)이 가나자와역에서 성까지 걷고, 아사노강에는 등롱을 띄운다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('스미다강 불꽃놀이', '隅田川花火大会', '東京都', '台東区・墨田区', DATE '2027-07-31', DATE '2027-07-31', 2027, 35.711000, 139.802000, '에도 시대 료고쿠 불꽃에서 이어진 도쿄 대표 불꽃놀이. 두 회장에서 약 2만 발이 오르고, 아사쿠사·스카이트리 주변이 인파로 가득 찬다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나가오카 불꽃축제', '長岡まつり大花火大会', '新潟県', '長岡市', DATE '2027-08-02', DATE '2027-08-03', 2027, 37.450000, 138.840000, '일본 3대 불꽃놀이 중 하나로, 공습 희생자 위령과 평화 기원을 담아 신노가와 강변에서 열린다. 폭 2km에 이르는 ''피닉스''가 대표 프로그램이다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('군조오도리 (철야 춤)', '郡上おどり 徹夜おどり', '岐阜県', '郡上市', DATE '2027-08-13', DATE '2027-08-16', 2027, 35.749000, 136.962000, '물의 마을 군조하치만에서 오봉 나흘간 밤새 이어지는 봉오도리. 관객과 연기자의 구분 없이 유카타 차림으로 누구나 원에 들어가 아침까지 춤춘다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('엣추 야쓰오 오와라 가제노본', '越中八尾 おわら風の盆', '富山県', '富山市', DATE '2027-09-01', DATE '2027-09-03', 2027, 36.573000, 137.153000, '언덕 위 옛 마을 야쓰오에서 호궁 가락에 맞춰 삿갓을 깊이 눌러쓴 무용수들이 조용히 거리를 걷는 축제. 밤이 깊을수록 분위기가 짙어진다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('사와라 대제 (가을 축제)', '佐原の大祭 秋祭り', '千葉県', '香取市', DATE '2027-10-08', DATE '2027-10-10', 2027, 35.889000, 140.499000, '수로를 따라 에도 시대 상가가 남은 사와라 거리를 큰 인형을 올린 수레가 도는 축제. 300년 역사로 유네스코 무형유산 ''야마·호코·야타이 행사''에 들어간다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('다카야마 마쓰리 (가을)', '秋の高山祭（八幡祭）', '岐阜県', '高山市', DATE '2027-10-09', DATE '2027-10-10', 2027, 36.148000, 137.262000, '사쿠라야마 하치만궁의 제례로 봄 축제와 짝을 이루는 다카야마의 가을 축제. 수레 11기가 하치만궁 참도에 늘어서고, 밤에는 등불을 단 수레가 거리를 돈다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('가와고에 마쓰리', '川越まつり', '埼玉県', '川越市', DATE '2027-10-16', DATE '2027-10-17', 2027, 35.920000, 139.485000, '''작은 에도'' 가와고에의 옛 거리를 화려한 수레가 도는 축제. 수레끼리 마주 보며 반주를 겨루는 ''힛카와세''가 밤에 절정을 맞는다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나고야 마쓰리', '名古屋まつり', '愛知県', '名古屋市中区', DATE '2027-10-16', DATE '2027-10-17', 2027, 35.170000, 136.909000, '나고야 출신 세 무장 노부나가·히데요시·이에야스를 내세운 ''향토 영웅 행렬''이 중심가를 걷는 축제. 꽃수레와 가라쿠리 수레도 함께 나온다.', NULL, NULL, NULL, NULL);